input.command:
cd /tmp && cat > sqt.c <<'EOF'
typedef struct sqlite3 sqlite3;
extern int sqlite3_open(const char*, sqlite3**);
extern const char* sqlite3_libversion(void);
#include <stdio.h>
int main(){ sqlite3*db; sqlite3_open(":memory:",&db); printf("ok %s\n", sqlite3_libversion()); return 0;}
EOF
gcc sqt.c -o sqt -l:libsqlite3.so.0 2>&1 | head -5 && ./sqt

cd /tmp/t1 && W(){ /workspace/executable -n -c ";$1" sys.log 2>&1 | head -1 | awk '{print length($0)-1}'; }
for q in "SELECT 1 AS c" "SELECT 22222 AS c" "SELECT 1234567890 AS c" "SELECT 12345678901 AS c" "SELECT 1 AS c UNION ALL SELECT NULL" "SELECT 1 AS c UNION ALL SELECT 'xxxxxxxx'" "SELECT 1.5 AS c" "SELECT 'x' AS c" "SELECT 'xxxxxxxxxxxx' AS c" "SELECT 1 AS abcdefghijkl"; do printf "%-45s width=%s\n" "$q" "$(W "$q")"; done
echo "=== alignment check:"; /workspace/executable -n -c ";SELECT 1 AS c UNION ALL SELECT 'xxxxxxxx'" sys.log 2>&1 | cat -A
